import { closeDatabase } from '../../src/server/db/connection.js';
import { runMigrations } from '../../src/server/db/migrations.js';
import { FIXED_NOW } from '../fixtures/bookmarks.js';
import {
  createTemporaryDatabase,
  type TemporaryDatabase,
} from '../fixtures/database.js';

interface TableListRow {
  name: string;
  strict: 0 | 1;
}

describe('database lifecycle', () => {
  let fixture: TemporaryDatabase | undefined;

  afterEach(() => {
    fixture?.cleanup();
    fixture = undefined;
  });

  it('migrates an empty file into all strict tables and planned indexes', () => {
    fixture = createTemporaryDatabase({ migrate: false });
    expect(
      fixture.database
        .prepare("SELECT name FROM sqlite_master WHERE type = 'table'")
        .all(),
    ).toEqual([]);

    runMigrations(fixture.database, undefined, () => FIXED_NOW);

    const tables = fixture.database
      .prepare("SELECT name, strict FROM pragma_table_list WHERE name NOT LIKE 'sqlite_%'")
      .all() as TableListRow[];
    expect(tables).toEqual(
      expect.arrayContaining([
        { name: 'bookmarks', strict: 1 },
        { name: 'tags', strict: 1 },
        { name: 'bookmark_tags', strict: 1 },
        { name: 'schema_migrations', strict: 1 },
      ]),
    );

    const indexes = (
      fixture.database
        .prepare("SELECT name FROM sqlite_master WHERE type = 'index' AND name NOT LIKE 'sqlite_%'")
        .all() as Array<{ name: string }>
    ).map(({ name }) => name);
    expect(indexes).toEqual(
      expect.arrayContaining([
        'idx_bookmarks_url_key',
        'idx_bookmarks_reading_created',
        'idx_bookmarks_created',
        'idx_bookmark_tags_tag_bookmark',
      ]),
    );
    expect(
      fixture.database.prepare('SELECT * FROM schema_migrations').all(),
    ).toEqual([{ version: 1, name: 'initial', applied_at: FIXED_NOW }]);
  });

  it('is idempotent when migrations run again', () => {
    fixture = createTemporaryDatabase({ now: () => FIXED_NOW });
    runMigrations(fixture.database, undefined, () => '2099-01-01T00:00:00.000Z');

    expect(
      fixture.database.prepare('SELECT * FROM schema_migrations').all(),
    ).toEqual([{ version: 1, name: 'initial', applied_at: FIXED_NOW }]);
  });

  it('enforces foreign keys and cascades association deletion', () => {
    fixture = createTemporaryDatabase();
    const { database } = fixture;

    expect(database.pragma('foreign_keys', { simple: true })).toBe(1);
    expect(() =>
      database
        .prepare('INSERT INTO bookmark_tags (bookmark_id, tag_id) VALUES (?, ?)')
        .run('missing-bookmark', 'missing-tag'),
    ).toThrow(/FOREIGN KEY constraint failed/);

    database
      .prepare(
        `INSERT INTO bookmarks
          (id, url, url_key, title, description, reading_state, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        'bookmark-1',
        'https://example.com/',
        'https://example.com/',
        'Example',
        '',
        'untracked',
        FIXED_NOW,
        FIXED_NOW,
      );
    database
      .prepare('INSERT INTO tags (id, display_name, normalized_name) VALUES (?, ?, ?)')
      .run('tag-1', 'Research', 'research');
    database
      .prepare('INSERT INTO bookmark_tags (bookmark_id, tag_id) VALUES (?, ?)')
      .run('bookmark-1', 'tag-1');

    database.prepare('DELETE FROM bookmarks WHERE id = ?').run('bookmark-1');
    expect(database.prepare('SELECT * FROM bookmark_tags').all()).toEqual([]);
  });

  it('persists rows across close and reopen and configures each connection', () => {
    fixture = createTemporaryDatabase();
    fixture.database
      .prepare(
        `INSERT INTO bookmarks
          (id, url, url_key, title, description, reading_state, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(
        'bookmark-1',
        'https://example.com/',
        'https://example.com/',
        'Persistent bookmark',
        '',
        'to_read',
        FIXED_NOW,
        FIXED_NOW,
      );
    closeDatabase(fixture.database);

    const reopened = fixture.openConnection();
    expect(reopened.pragma('foreign_keys', { simple: true })).toBe(1);
    expect(reopened.pragma('journal_mode', { simple: true })).toBe('wal');
    expect(
      reopened.prepare('SELECT title, reading_state FROM bookmarks').get(),
    ).toEqual({ title: 'Persistent bookmark', reading_state: 'to_read' });
    expect(reopened.prepare('SELECT COUNT(*) AS count FROM schema_migrations').get()).toEqual({
      count: 1,
    });
  });
});
import {
  canonicalizeBookmarkUrl,
  createUrlKey,
  normalizeBookmarkUrl,
  normalizeTag,
  normalizeTagName,
  normalizeTags,
} from '../../src/shared/normalization.js';

describe('bookmark URL normalization', () => {
  it('trims and applies WHATWG scheme, host, and default-port canonicalization', () => {
    expect(canonicalizeBookmarkUrl('  HTTPS://Example.COM:443/docs  ')).toBe(
      'https://example.com/docs',
    );
  });

  it('retains the fragment for navigation and removes it from duplicate keys', () => {
    expect(normalizeBookmarkUrl('https://example.com/docs?q=one#intro')).toEqual({
      url: 'https://example.com/docs?q=one#intro',
      urlKey: 'https://example.com/docs?q=one',
    });
    expect(createUrlKey('https://example.com/docs?q=two#intro')).toBe(
      'https://example.com/docs?q=two',
    );
  });

  it.each(['ftp://example.com/file', 'mailto:user@example.com']) (
    'rejects unsupported protocol %s',
    (url) => expect(() => canonicalizeBookmarkUrl(url)).toThrow(/HTTP or HTTPS/),
  );

  it('rejects embedded credentials', () => {
    expect(() => createUrlKey('https://user:secret@example.com/')).toThrow(
      /credentials/,
    );
  });
});

describe('tag normalization', () => {
  it('trims, compatibility-normalizes, and lowercases identity values', () => {
    expect(normalizeTagName('  Ｄｅｓｉｇｎ  ')).toBe('design');
    expect(normalizeTag('  Research  ')).toEqual({
      displayName: 'Research',
      normalizedName: 'research',
    });
  });

  it('deduplicates normalized identities while retaining first spelling and order', () => {
    expect(normalizeTags([' Design ', 'RESEARCH', 'ｄｅｓｉｇｎ', 'research'])).toEqual([
      { displayName: 'Design', normalizedName: 'design' },
      { displayName: 'RESEARCH', normalizedName: 'research' },
    ]);
  });
});
import {
  bookmarkDescriptionSchema,
  bookmarkIdSchema,
  bookmarkInputSchema,
  bookmarkListQuerySchema,
  bookmarkTagsSchema,
  bookmarkTitleSchema,
  bookmarkUrlSchema,
  pageMetadataRequestSchema,
  readingStateSchema,
  readingStateUpdateSchema,
  sortOrderSchema,
  tagNameSchema,
} from '../../src/shared/schemas.js';

const atExactLength = (prefix: string, length: number): string =>
  prefix + 'a'.repeat(length - [...prefix].length);

describe('bookmark URL schema', () => {
  it.each(['http://example.com', 'https://example.com/path?query=yes#part'])(
    'accepts supported absolute URL %s',
    (url) => expect(bookmarkUrlSchema.parse(` ${url} `)).toBe(url),
  );

  it.each([
    '',
    'not a URL',
    '/relative',
    'ftp://example.com/file',
    'https://user@example.com/',
    'https://:password@example.com/',
  ])('rejects invalid or unsupported URL %j', (url) => {
    expect(bookmarkUrlSchema.safeParse(url).success).toBe(false);
  });

  it('enforces the inclusive 4,096-code-point boundary', () => {
    const valid = atExactLength('https://example.com/', 4_096);
    const invalid = `${valid}a`;
    expect(bookmarkUrlSchema.safeParse(valid).success).toBe(true);
    expect(bookmarkUrlSchema.safeParse(invalid).success).toBe(false);
  });
});

describe('bookmark text and tag schemas', () => {
  it('trims titles and enforces non-empty and 300-code-point boundaries', () => {
    expect(bookmarkTitleSchema.parse('  Useful page  ')).toBe('Useful page');
    expect(bookmarkTitleSchema.safeParse('   ').success).toBe(false);
    expect(bookmarkTitleSchema.safeParse('😀'.repeat(300)).success).toBe(true);
    expect(bookmarkTitleSchema.safeParse('😀'.repeat(301)).success).toBe(false);
  });

  it('allows an empty description, trims it, and caps it at 2,000 code points', () => {
    expect(bookmarkDescriptionSchema.parse('   ')).toBe('');
    expect(bookmarkDescriptionSchema.parse('  Notes  ')).toBe('Notes');
    expect(bookmarkDescriptionSchema.safeParse('😀'.repeat(2_000)).success).toBe(true);
    expect(bookmarkDescriptionSchema.safeParse('😀'.repeat(2_001)).success).toBe(false);
  });

  it('enforces trimmed and normalized tag boundaries', () => {
    expect(tagNameSchema.parse('  Research  ')).toBe('Research');
    expect(tagNameSchema.safeParse(' ').success).toBe(false);
    expect(tagNameSchema.safeParse('😀'.repeat(40)).success).toBe(true);
    expect(tagNameSchema.safeParse('😀'.repeat(41)).success).toBe(false);
    expect(tagNameSchema.safeParse('ﬃ'.repeat(14)).success).toBe(false);
  });

  it('allows at most 20 tags', () => {
    expect(bookmarkTagsSchema.safeParse(Array.from({ length: 20 }, (_, i) => `tag-${i}`)).success)
      .toBe(true);
    expect(bookmarkTagsSchema.safeParse(Array.from({ length: 21 }, (_, i) => `tag-${i}`)).success)
      .toBe(false);
  });
});

describe('composed request schemas', () => {
  it('applies bookmark defaults, trims fields, and rejects unknown properties', () => {
    expect(
      bookmarkInputSchema.parse({ url: ' https://example.com ', title: ' Example ' }),
    ).toEqual({
      url: 'https://example.com',
      title: 'Example',
      description: '',
      tags: [],
      readingState: 'untracked',
      allowDuplicate: false,
    });
    expect(
      bookmarkInputSchema.safeParse({
        url: 'https://example.com',
        title: 'Example',
        unexpected: true,
      }).success,
    ).toBe(false);
  });

  it.each(['untracked', 'to_read', 'read'])(
    'accepts reading state %s',
    (state) => expect(readingStateSchema.safeParse(state).success).toBe(true),
  );

  it('rejects invalid reading states and strict update extras', () => {
    expect(readingStateSchema.safeParse('later').success).toBe(false);
    expect(
      readingStateUpdateSchema.safeParse({ readingState: 'read', extra: true }).success,
    ).toBe(false);
  });

  it.each(['newest', 'oldest', 'title'])(
    'accepts sort order %s',
    (sort) => expect(sortOrderSchema.safeParse(sort).success).toBe(true),
  );

  it('defaults and normalizes list query fields', () => {
    expect(bookmarkListQuerySchema.parse({})).toEqual({
      view: 'all',
      query: '',
      tag: [],
      sort: 'newest',
    });
    expect(bookmarkListQuerySchema.parse({ tag: ' Research ', query: ' term ' })).toEqual({
      view: 'all',
      query: 'term',
      tag: ['Research'],
      sort: 'newest',
    });
    expect(bookmarkListQuerySchema.safeParse({ query: '😀'.repeat(300) }).success).toBe(true);
    expect(bookmarkListQuerySchema.safeParse({ query: '😀'.repeat(301) }).success).toBe(false);
    expect(bookmarkListQuerySchema.safeParse({ view: 'queue' }).success).toBe(false);
  });

  it('reuses URL validation for metadata requests', () => {
    expect(pageMetadataRequestSchema.parse({ url: ' https://example.com ' })).toEqual({
      url: 'https://example.com',
    });
    expect(pageMetadataRequestSchema.safeParse({ url: 'file:///etc/passwd' }).success).toBe(false);
    expect(pageMetadataRequestSchema.safeParse({ url: 'https://example.com', extra: true }).success)
      .toBe(false);
  });

  it('accepts only UUID bookmark identifiers', () => {
    expect(bookmarkIdSchema.safeParse('00000000-0000-4000-8000-000000000001').success)
      .toBe(true);
    expect(bookmarkIdSchema.safeParse('bookmark-1').success).toBe(false);
  });
});
