  createId?: () => string;
}

const DEFAULT_QUERY: ResolvedBookmarkListQuery = {
  view: 'all',
  query: '',
  tag: [],
  sort: 'newest',
};

export class BookmarkRepository {
  private readonly now: () => string;
  private readonly createId: () => string;

  constructor(
    private readonly database: BookmarkDatabase,
    options: BookmarkRepositoryOptions = {},
  ) {
    this.now = options.now ?? (() => new Date().toISOString());
    this.createId = options.createId ?? (() => crypto.randomUUID());
  }

  private tagsForBookmark(bookmarkId: string): string[] {
    const rows = this.database
      .prepare(
        `SELECT t.display_name AS name
         FROM bookmark_tags bt
         JOIN tags t ON t.id = bt.tag_id
         WHERE bt.bookmark_id = ?
         ORDER BY bt.rowid ASC`,
      )
      .all(bookmarkId) as Array<{ name: string }>;
    return rows.map(({ name }) => name);
  }

  private mapRow(row: BookmarkRow): Bookmark {
    return {
      id: row.id,
      url: row.url,
      title: row.title,
      description: row.description,
      tags: this.tagsForBookmark(row.id),
      readingState: row.reading_state,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }

  get(bookmarkId: string): Bookmark | null {
    const row = this.database
      .prepare(
        `SELECT id, url, title, description, reading_state, created_at, updated_at
         FROM bookmarks WHERE id = ?`,
      )
      .get(bookmarkId) as BookmarkRow | undefined;
    return row ? this.mapRow(row) : null;
  }

  findDuplicate(urlKey: string, excludeId?: string): Bookmark | null {
    const row = this.database
      .prepare(
        `SELECT id, url, title, description, reading_state, created_at, updated_at
         FROM bookmarks
         WHERE url_key = ? AND (? IS NULL OR id <> ?)
         ORDER BY created_at ASC, id ASC
         LIMIT 1`,
      )
      .get(urlKey, excludeId ?? null, excludeId ?? null) as BookmarkRow | undefined;
    return row ? this.mapRow(row) : null;
  }

  create(record: CreateBookmarkRecord): Bookmark {
    const createTransaction = this.database.transaction(() => {
      const id = this.createId();
      const timestamp = this.now();
      this.database
        .prepare(
          `INSERT INTO bookmarks
           (id, url, url_key, title, description, reading_state, created_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(
          id,
          record.url,
          record.urlKey,
          record.title,
          record.description,
          record.readingState,
          timestamp,
          timestamp,
        );

      const findTag = this.database.prepare(
        'SELECT id FROM tags WHERE normalized_name = ?',
      );
      const insertTag = this.database.prepare(
        'INSERT INTO tags (id, display_name, normalized_name) VALUES (?, ?, ?)',
      );
      const attachTag = this.database.prepare(
        'INSERT INTO bookmark_tags (bookmark_id, tag_id) VALUES (?, ?)',
      );

      for (const tag of record.tags) {
        const existing = findTag.get(tag.normalizedName) as { id: string } | undefined;
        const tagId = existing?.id ?? this.createId();
        if (!existing) insertTag.run(tagId, tag.displayName, tag.normalizedName);
        attachTag.run(id, tagId);
      }

      return id;
    });

    const id = createTransaction();
    const bookmark = this.get(id);
    if (!bookmark) throw new Error('Created bookmark could not be loaded.');
    return bookmark;
  }

  list(query: ResolvedBookmarkListQuery = DEFAULT_QUERY): Bookmark[] {
    const conditions: string[] = [];
    const parameters: Array<string | number> = [];

    if (query.view === 'read-later') conditions.push("b.reading_state = 'to_read'");

    const where = conditions.length ? `WHERE ${conditions.join(' AND ')}` : '';
    const order =
      query.sort === 'oldest'
        ? 'b.created_at ASC, b.id ASC'
        : query.sort === 'title'
          ? 'lower(b.title) ASC, b.id ASC'
          : 'b.created_at DESC, b.id ASC';

    const rows = this.database
      .prepare(
        `SELECT b.id, b.url, b.title, b.description, b.reading_state, b.created_at, b.updated_at
         FROM bookmarks b ${where}
         ORDER BY ${order}`,
      )
      .all(...parameters) as BookmarkRow[];
    return rows.map((row) => this.mapRow(row));
  }

  delete(bookmarkId: string): boolean {
    const remove = this.database.transaction(() => {
      const result = this.database.prepare('DELETE FROM bookmarks WHERE id = ?').run(bookmarkId);
      if (result.changes > 0) {
        this.database.prepare(
          'DELETE FROM tags WHERE NOT EXISTS (SELECT 1 FROM bookmark_tags WHERE tag_id = tags.id)',
        ).run();
      }
      return result.changes > 0;
    });
    return remove();
  }

  updateReadingState(bookmarkId: string, readingState: ReadingState): Bookmark | null {
    const result = this.database
      .prepare(
        `UPDATE bookmarks
         SET reading_state = ?, updated_at = ?
         WHERE id = ?`,
      )
      .run(readingState, this.now(), bookmarkId);
    return result.changes > 0 ? this.get(bookmarkId) : null;
  }
}
import type {
  Bookmark,
  BookmarkInput,
  BookmarkList,
  BookmarkListQuery,
} from '../../shared/contracts.js';
import { normalizeBookmarkUrl, normalizeTags } from '../../shared/normalization.js';
import {
  bookmarkIdSchema,
  bookmarkInputSchema,
  bookmarkListQuerySchema,
  readingStateSchema,
} from '../../shared/schemas.js';
import type { BookmarkRepository } from '../db/bookmark-repository.js';

export class DuplicateBookmarkError extends Error {
  public readonly statusCode = 409;
  public readonly code = 'DUPLICATE_URL';

  constructor(public readonly existingBookmark: Bookmark) {
    super('This web address is already saved in your library.');
  }
}

export class BookmarkNotFoundError extends Error {
  public readonly statusCode = 404;
  public readonly code = 'BOOKMARK_NOT_FOUND';

  constructor() {
    super('The requested bookmark was not found.');
  }
}

export class BookmarkService {
  constructor(private readonly repository: BookmarkRepository) {}

  createBookmark(input: BookmarkInput): Bookmark {
    const validated = bookmarkInputSchema.parse(input);
    const normalizedUrl = normalizeBookmarkUrl(validated.url);
    const tags = normalizeTags(validated.tags);

    const duplicate = this.repository.findDuplicate(normalizedUrl.urlKey);
    if (duplicate && !validated.allowDuplicate) throw new DuplicateBookmarkError(duplicate);

    return this.repository.create({
      url: normalizedUrl.url,
      urlKey: normalizedUrl.urlKey,
      title: validated.title,
      description: validated.description,
      tags,
      readingState: validated.readingState,
    });
  }

  getBookmark(bookmarkId: string): Bookmark {
    const id = bookmarkIdSchema.parse(bookmarkId);
    const bookmark = this.repository.get(id);
    if (!bookmark) throw new BookmarkNotFoundError();
    return bookmark;
  }

  listBookmarks(query: BookmarkListQuery = {}): BookmarkList {
    const validated = bookmarkListQuerySchema.parse(query);
    const items = this.repository.list(validated);
    return { items, total: items.length };
  }

  deleteBookmark(bookmarkId: string): void {
    const id = bookmarkIdSchema.parse(bookmarkId);
    if (!this.repository.delete(id)) throw new BookmarkNotFoundError();
  }

  updateReadingState(bookmarkId: string, readingState: unknown): Bookmark {
    const id = bookmarkIdSchema.parse(bookmarkId);
    const state = readingStateSchema.parse(readingState);
    const bookmark = this.repository.updateReadingState(id, state);
    if (!bookmark) throw new BookmarkNotFoundError();
    return bookmark;
  }
}
import type { Express, Request } from 'express';

import type { BookmarkService } from '../services/bookmark-service.js';
import { readingStateUpdateSchema } from '../../shared/schemas.js';

export interface BookmarkRouteDependencies {
  bookmarkService: BookmarkService;
}

function listQuery(request: Request): Record<string, unknown> {
  const tag = request.query.tag;
  return {
    ...(request.query.view === undefined ? {} : { view: request.query.view }),
    ...(request.query.query === undefined ? {} : { query: request.query.query }),
    ...(tag === undefined ? {} : { tag }),
    ...(request.query.sort === undefined ? {} : { sort: request.query.sort }),
  };
}

export function registerBookmarkRoutes(
  app: Express,
  { bookmarkService }: BookmarkRouteDependencies,
): void {
  app.get('/api/bookmarks', (request, response) => {
    response.json(bookmarkService.listBookmarks(listQuery(request)));
  });

  app.post('/api/bookmarks', (request, response) => {
    response.status(201).json(bookmarkService.createBookmark(request.body));
  });

  app.get('/api/bookmarks/:bookmarkId', (request, response) => {
    response.json(bookmarkService.getBookmark(request.params.bookmarkId ?? ''));
  });

  app.delete('/api/bookmarks/:bookmarkId', (request, response) => {
    bookmarkService.deleteBookmark(request.params.bookmarkId ?? '');
    response.status(204).send();
  });

  app.patch('/api/bookmarks/:bookmarkId/reading-state', (request, response) => {
    const input = readingStateUpdateSchema.parse(request.body);
    response.json(
      bookmarkService.updateReadingState(request.params.bookmarkId ?? '', input.readingState),
    );
  });
}
# Data Model: Personal Bookmark Manager

**Date**: 2026-09-26  
**Source**: [Approved specification](spec.md)

## Overview

SQLite is the durable source of truth. The model separates bookmark details from reusable, case-insensitive tags. Library view state is represented in the browser URL and is not persisted in the database.

## Bookmark

Represents one saved web resource.

| Field | Storage | Required | Rules |
|---|---|---:|---|
| `id` | text | Yes | UUID generated by the server; immutable primary key |
| `url` | text | Yes | Trimmed absolute HTTP(S) URL, at most 4,096 characters; no embedded username/password |
| `url_key` | text | Yes | Normalized key used for duplicate warnings; indexed but not unique |
| `title` | text | Yes | Trimmed, 1–300 Unicode code points |
| `description` | text | Yes | Empty string or trimmed text up to 2,000 Unicode code points |
| `reading_state` | text | Yes | `untracked`, `to_read`, or `read`; defaults to `untracked` |
| `created_at` | text | Yes | UTC ISO-8601 timestamp assigned once by the server |
| `updated_at` | text | Yes | UTC ISO-8601 timestamp changed on each successful update |

### URL normalization

The server parses the submitted URL once with the WHATWG URL parser, trims surrounding whitespace, requires `http:` or `https:`, rejects credentials, and serializes the canonical form for storage. `url_key` additionally removes the fragment because it is not part of the network resource used for duplicate detection. Path and query remain significant. Scheme/host casing and default-port normalization come from the URL parser.

Examples:

| Submitted URL | Stored URL | Duplicate key |
|---|---|---|
| `HTTPS://Example.COM:443/docs#intro` | `https://example.com/docs#intro` | `https://example.com/docs` |
| `https://example.com/docs?lang=en` | same canonical form | `https://example.com/docs?lang=en` |

Two rows may share `url_key` after the user explicitly acknowledges the duplicate warning.

### Reading-state transitions

```text
untracked ──mark To Read──> to_read ──mark Read──> read
    ▲                         ▲                     │
    └────mark Untracked───────┴────mark To Read────┘
```

- A new bookmark defaults to `untracked` unless the create request specifies another state.
- `to_read` membership is the sole criterion for the Read Later view.
- Moving to `read` or `untracked` removes the bookmark from Read Later but never deletes it.
- Any state may transition to any other valid state through edit or the focused reading-state action.

## Tag

Represents a reusable organizational label.

| Field | Storage | Required | Rules |
|---|---|---:|---|
| `id` | text | Yes | UUID generated by the server; immutable primary key |
| `display_name` | text | Yes | Trimmed first-entered spelling, 1–40 Unicode code points |
| `normalized_name` | text | Yes | Trimmed, Unicode NFKC-normalized, lowercased key; unique |

`Design`, ` design `, and equivalent Unicode compatibility forms resolve to one tag. The original display spelling is preserved until the tag becomes unused and is removed.

## BookmarkTag

Associates bookmarks with tags.

| Field | Storage | Required | Rules |
|---|---|---:|---|
| `bookmark_id` | text | Yes | Foreign key to Bookmark, cascading on delete |
| `tag_id` | text | Yes | Foreign key to Tag, cascading on delete |

The pair is the primary key, preventing the same normalized tag from appearing twice on one bookmark. A bookmark may have at most 20 tags. Tags left with no bookmarks after an update or deletion are removed in the same transaction.

## SchemaMigration

Tracks applied schema changes.

| Field | Storage | Required | Rules |
|---|---|---:|---|
| `version` | integer | Yes | Monotonically increasing primary key |
| `name` | text | Yes | Human-readable migration identifier |
| `applied_at` | text | Yes | UTC ISO-8601 timestamp |

## Relational Shape

```text
Bookmark 1 ─────< BookmarkTag >───── 1 Tag
```

Initial indexes:

- `bookmarks(url_key)` for duplicate lookup.
- `bookmarks(reading_state, created_at, id)` for the Read Later default order.
- `bookmarks(created_at, id)` for newest/oldest sorting.
- `bookmark_tags(tag_id, bookmark_id)` for tag filtering.
- The unique index on `tags.normalized_name` enforces case-insensitive tag identity after application normalization.

## Mutation Invariants

1. Create/update bookmark details and all tag associations in one transaction.
2. Validate and normalize every value before executing SQL; also enforce required values and reading-state/tag-length checks in the database.
3. Use prepared statements for every user-controlled value.
4. On update, exclude the current bookmark ID from duplicate lookup.
5. If another bookmark has the same `url_key` and `allowDuplicate` is false, roll back and return the existing bookmark summary.
6. If any tag or association operation fails, the bookmark mutation rolls back completely.
7. After successful deletion or tag replacement, remove tags that no longer have associations.
8. `created_at` never changes; `updated_at` changes only after a successful mutation.

## Derived Query Model

The API returns each bookmark with its ordered tag array; association rows are not exposed directly.

Query processing follows this order:

1. Select `all` bookmarks or only `reading_state = 'to_read'`.
2. If tags are selected, retain bookmarks associated with every normalized selected tag (AND semantics).
3. If a search term is present, match it case-insensitively against title, URL, description, or any tag display name.
4. Sort by newest (`created_at DESC`), oldest (`created_at ASC`), or title (normalized title ascending). Add `id ASC` as a deterministic tie-breaker.
5. Return `{ items, total }` and obtain the available tag list separately from `GET /api/tags`.

## Non-persisted View State

The client encodes the following in URL query parameters:

- `view`: `library` or `read-later`
- `query`: current search text
- `tag`: zero or more selected normalized tag names
- `sort`: `newest`, `oldest`, or `title`

This state changes presentation only and never mutates a bookmark.
---

