openapi: 3.1.0
info:
  title: Personal Bookmark Manager API
  version: 1.0.0
  description: Same-origin JSON API for the approved single-user bookmark application.
  license:
    name: Unlicensed
servers:
  - url: /api
security: []
paths:
  /health:
    get:
      operationId: getHealth
      summary: Report whether the application and database are ready.
      responses:
        "200":
          description: Ready
          content:
            application/json:
              schema:
                type: object
                required: [status]
                properties:
                  status:
                    const: ok

  /bookmarks:
    get:
      operationId: listBookmarks
      summary: List bookmarks in the full library or Read Later view.
      parameters:
        - name: view
          in: query
          schema:
            type: string
            enum: [all, read-later]
            default: all
        - name: query
          in: query
          schema:
            type: string
            maxLength: 300
        - name: tag
          in: query
          description: Repeat to require every selected normalized tag.
          style: form
          explode: true
          schema:
            type: array
            maxItems: 20
            items:
              type: string
              minLength: 1
              maxLength: 40
        - name: sort
          in: query
          schema:
            $ref: "#/components/schemas/SortOrder"
      responses:
        "200":
          description: Matching bookmarks
          content:
            application/json:
              schema:
                $ref: "#/components/schemas/BookmarkList"
        "422":
          $ref: "#/components/responses/ValidationError"
        "500":
          $ref: "#/components/responses/InternalError"
    post:
      operationId: createBookmark
      summary: Save a bookmark.
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: "#/components/schemas/BookmarkInput"
      responses:
        "201":
          description: Bookmark created
          content:
            application/json:
              schema:
                $ref: "#/components/schemas/Bookmark"
        "409":
          $ref: "#/components/responses/DuplicateUrl"
        "422":
          $ref: "#/components/responses/ValidationError"
        "500":
          $ref: "#/components/responses/InternalError"

  /bookmarks/{bookmarkId}:
    parameters:
      - $ref: "#/components/parameters/BookmarkId"
    get:
      operationId: getBookmark
      summary: Get one bookmark.
      responses:
        "200":
          description: Bookmark found
          content:
            application/json:
              schema:
                $ref: "#/components/schemas/Bookmark"
        "404":
          $ref: "#/components/responses/NotFound"
    put:
      operationId: replaceBookmark
      summary: Replace editable bookmark details.
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: "#/components/schemas/BookmarkInput"
      responses:
        "200":
          description: Bookmark updated
          content:
            application/json:
              schema:
                $ref: "#/components/schemas/Bookmark"
        "404":
          $ref: "#/components/responses/NotFound"
        "409":
          $ref: "#/components/responses/DuplicateUrl"
        "422":
          $ref: "#/components/responses/ValidationError"
        "500":
          $ref: "#/components/responses/InternalError"
    delete:
      operationId: deleteBookmark
      summary: Permanently delete a bookmark after UI confirmation.
      responses:
        "204":
          description: Bookmark deleted
        "404":
          $ref: "#/components/responses/NotFound"
        "500":
          $ref: "#/components/responses/InternalError"

  /bookmarks/{bookmarkId}/reading-state:
    parameters:
      - $ref: "#/components/parameters/BookmarkId"
    patch:
      operationId: updateReadingState
      summary: Change only the reading state.
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
              additionalProperties: false
              required: [readingState]
              properties:
                readingState:
                  $ref: "#/components/schemas/ReadingState"
      responses:
        "200":
          description: Reading state changed
          content:
            application/json:
              schema:
                $ref: "#/components/schemas/Bookmark"
        "404":
          $ref: "#/components/responses/NotFound"
        "422":
          $ref: "#/components/responses/ValidationError"
        "500":
          $ref: "#/components/responses/InternalError"

  /tags:
    get:
      operationId: listTags
      summary: List tags currently attached to at least one bookmark.
      responses:
        "200":
          description: Current tags ordered by display name
          content:
            application/json:
              schema:
                type: object
                additionalProperties: false
                required: [items]
                properties:
                  items:
                    type: array
                    items:
                      $ref: "#/components/schemas/Tag"
        "500":
          $ref: "#/components/responses/InternalError"

  /page-metadata:
    post:
      operationId: previewPageMetadata
      summary: Retrieve safe, best-effort title and description suggestions.
      description: >-
        An unavailable outcome is non-blocking and does not determine whether the
        bookmark itself may be saved. The endpoint never returns fetched HTML.
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
              additionalProperties: false
              required: [url]
              properties:
                url:
                  type: string
                  minLength: 1
                  maxLength: 4096
      responses:
        "200":
          description: Retrieval completed, partially completed, or safely became unavailable.
