      ),
    ).toThrow(/forced tag failure/);

    expect(rowCount(fixture.database, 'bookmarks')).toBe(0);
    expect(rowCount(fixture.database, 'tags')).toBe(0);
    expect(rowCount(fixture.database, 'bookmark_tags')).toBe(0);
  });

