import { Component, useCallback, useEffect, useState, type ErrorInfo, type ReactNode } from 'react';

import type { Bookmark, Tag } from '../shared/contracts.js';
import {
  deleteBookmark,
  listBookmarks,
  updateBookmarkReadingState,
} from './api/bookmarks.js';
import { listTags } from './api/tags.js';
import { BookmarkForm } from './features/bookmarks/BookmarkForm.js';
import { BookmarkList } from './features/bookmarks/BookmarkList.js';
import { LibraryTabs } from './features/bookmarks/LibraryTabs.js';
import { LibraryControls } from './features/bookmarks/LibraryControls.js';
import { useLibraryView } from './features/bookmarks/useLibraryView.js';

export function App() {
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingBookmark, setEditingBookmark] = useState<Bookmark | undefined>();
  const [tags, setTags] = useState<Tag[]>([]);
  const {
    view,
    query,
    tags: selectedTags,
    sort,
    setView,
    setQuery,
    setTags: setSelectedTags,
    setSort,
    clearCriteria,
  } = useLibraryView();

  const load = useCallback(async () => {
    try {
      const result = await listBookmarks({ view, query, tag: selectedTags, sort });
      setBookmarks(result.items);
      setLoaded(true);
      setErrorMessage('');
    } catch {
      setErrorMessage('Your bookmarks could not be loaded.');
    }
  }, [query, selectedTags, sort, view]);

  const loadTags = useCallback(async () => {
    try {
      setTags((await listTags()).items);
    } catch {
      // Bookmark data remains usable when the supporting tag list cannot refresh.
    }
  }, []);

  useEffect(() => {
    void load();
    void loadTags();
  }, [load, loadTags]);

  const handleSaved = (_bookmark: Bookmark) => {
    setLoaded(true);
    setErrorMessage('');
    setShowForm(false);
    setEditingBookmark(undefined);
    void load();
    void loadTags();
    window.setTimeout(() => document.getElementById('library-tab')?.focus(), 0);
  };

  const handleDelete = async (bookmark: Bookmark) => {
    try {
      await deleteBookmark(bookmark.id);
      await Promise.all([load(), loadTags()]);
      window.setTimeout(() => document.getElementById('library-tab')?.focus(), 0);
    } catch {
      setErrorMessage('The bookmark could not be deleted.');
    }
  };

  const handleReadingStateChange = async (
    bookmark: Bookmark,
    readingState: Bookmark['readingState'],
  ) => {
    try {
      const updated = await updateBookmarkReadingState(bookmark.id, readingState);
      setBookmarks((current) =>
        view === 'read-later' && updated.readingState !== 'to_read'
          ? current.filter(({ id }) => id !== updated.id)
          : current.map((item) => (item.id === updated.id ? updated : item)),
      );
      setErrorMessage('');
    } catch {
      setErrorMessage('The reading status could not be changed.');
    }
  };

  return (
    <main {...(loaded ? { 'data-harness-ready': 'true' } : {})}>
      <header>
        <a href="/" aria-label="Trove home">Trove</a>
        <div>
          <p>Personal bookmark library</p>
          <h1>Your bookmarks, kept close.</h1>
          <p>Save useful corners of the web and return when the time is right.</p>
        </div>
        <button
          type="button"
          onClick={() => {
            setEditingBookmark(undefined);
            setShowForm(true);
          }}
        >
          Add bookmark
        </button>
      </header>

      {showForm && (
        <section aria-labelledby="add-bookmark-heading">
          <h2 id="add-bookmark-heading">
            {editingBookmark ? 'Edit bookmark' : 'Add a bookmark'}
          </h2>
          <BookmarkForm
            key={editingBookmark?.id ?? 'create'}
            bookmark={editingBookmark}
            onSaved={handleSaved}
            onCancel={() => {
              setShowForm(false);
              setEditingBookmark(undefined);
            }}
          />
        </section>
      )}

      <LibraryTabs view={view} onChange={setView} />

      <LibraryControls
        query={query}
        selectedTags={selectedTags}
        sort={sort}
        tags={tags}
        onQueryChange={setQuery}
        onTagsChange={setSelectedTags}
        onSortChange={setSort}
      />

      <section
        id={view === 'all' ? 'library-tab-panel' : 'read-later-tab-panel'}
        role="tabpanel"
        aria-labelledby={view === 'all' ? 'library-tab' : 'read-later-tab'}
      >
        <div>
          <p>Collection</p>
          <h2>{view === 'all' ? 'Library' : 'Read Later'}</h2>
          {loaded && <p>{bookmarks.length} saved</p>}
        </div>

        {!loaded && !errorMessage && (
          <p role="status" aria-live="polite">
            Loading your bookmarks…
          </p>
        )}

        {errorMessage && (
          <div role="alert">
            <p>{errorMessage}</p>
            <button type="button" onClick={() => void load()}>
              Try again
            </button>
          </div>
        )}

        {loaded && (
          <BookmarkList
            bookmarks={bookmarks}
            emptyState={
              query || selectedTags.length > 0
                ? 'no-results'
                : view === 'read-later'
                  ? 'read-later'
                  : 'library'
            }
            onClearCriteria={clearCriteria}
            onReadingStateChange={(bookmark, readingState) =>
              void handleReadingStateChange(bookmark, readingState)
            }
            onEdit={(bookmark) => {
              setEditingBookmark(bookmark);
              setShowForm(true);
            }}
            onDelete={(bookmark) => void handleDelete(bookmark)}
          />
        )}
      </section>
    </main>
  );
}

interface AppErrorBoundaryProps {
  children: ReactNode;
}

interface AppErrorBoundaryState {
  hasError: boolean;
}

export class AppErrorBoundary extends Component<
  AppErrorBoundaryProps,
  AppErrorBoundaryState
> {
  public state: AppErrorBoundaryState = { hasError: false };

  public static getDerivedStateFromError(): AppErrorBoundaryState {
    return { hasError: true };
  }

  public componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error('The bookmark application could not be rendered.', error, info);
  }

  public render(): ReactNode {
    if (this.state.hasError) {
      return (
        <main>
          <h1>Trove</h1>
          <div role="alert">
            <h2>Something went wrong</h2>
            <p>Refresh the page to return to your bookmarks.</p>
          </div>
        </main>
      );
    }

    return this.props.children;
  }
}

export default App;
import { useEffect, useRef, type FormEvent } from 'react';

import type { Bookmark } from '../../../shared/contracts.js';
import { useBookmarkForm } from './useBookmarkForm.js';

export interface BookmarkFormProps {
  onSaved: (bookmark: Bookmark) => void;
  onCancel?: () => void;
  bookmark?: Bookmark;
}

export function BookmarkForm({ onSaved, onCancel, bookmark }: BookmarkFormProps) {
  const form = useBookmarkForm(onSaved, bookmark);
  const urlRef = useRef<HTMLInputElement>(null);
  const titleRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (form.fieldErrors.url) urlRef.current?.focus();
    else if (form.fieldErrors.title) titleRef.current?.focus();
  }, [form.fieldErrors]);

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault();
    await form.submit();
  };

  const describedBy = (field: string) =>
    form.fieldErrors[field] ? `${field}-error` : undefined;

  return (
    <form onSubmit={(event) => void handleSubmit(event)} noValidate>
      <div>
        <label htmlFor="bookmark-url">Web address</label>
        <input
          ref={urlRef}
          id="bookmark-url"
          name="url"
          type="url"
          value={form.fields.url}
          onChange={(event) => form.setUrl(event.target.value)}
          aria-invalid={Boolean(form.fieldErrors.url)}
          aria-describedby={describedBy('url')}
          autoFocus
        />
        {form.fieldErrors.url && <p id="url-error">{form.fieldErrors.url}</p>}
      </div>

      <p role="status" aria-live="polite">
        {form.metadataMessage}
      </p>

      <div>
        <label htmlFor="bookmark-title">Title</label>
        <input
          ref={titleRef}
          id="bookmark-title"
          name="title"
          value={form.fields.title}
          onChange={(event) => form.setTitle(event.target.value)}
          aria-invalid={Boolean(form.fieldErrors.title)}
          aria-describedby={describedBy('title')}
        />
        {form.fieldErrors.title && <p id="title-error">{form.fieldErrors.title}</p>}
      </div>

      <div>
        <label htmlFor="bookmark-description">Description</label>
        <textarea
          id="bookmark-description"
          name="description"
          value={form.fields.description}
          onChange={(event) => form.setDescription(event.target.value)}
          aria-invalid={Boolean(form.fieldErrors.description)}
          aria-describedby={describedBy('description')}
        />
        {form.fieldErrors.description && (
          <p id="description-error">{form.fieldErrors.description}</p>
        )}
      </div>

      <div>
        <label htmlFor="bookmark-tags">Tags</label>
        <input
          id="bookmark-tags"
          name="tags"
          value={form.fields.tags}
          onChange={(event) => form.setTags(event.target.value)}
          placeholder="research, design"
          aria-describedby="tags-hint"
        />
        <p id="tags-hint">Separate tags with commas.</p>
      </div>

      <div>
        <label htmlFor="bookmark-reading-state">Reading status</label>
        <select
          id="bookmark-reading-state"
          value={form.fields.readingState}
          onChange={(event) =>
            form.setReadingState(event.target.value as 'untracked' | 'to_read' | 'read')
          }
        >
          <option value="untracked">Untracked</option>
          <option value="to_read">To Read</option>
          <option value="read">Read</option>
        </select>
      </div>

      {form.submitMessage && !form.duplicate && <div role="alert">{form.submitMessage}</div>}
      {form.duplicate && (
        <div role="alert">
          <p>{form.submitMessage || 'This address is already saved.'}</p>
          <a
            href={form.duplicate.url}
            target="_blank"
            rel="noopener noreferrer"
          >
            Open existing bookmark
          </a>
          <button type="button" onClick={() => void form.submit(true)}>
            Save anyway
          </button>
        </div>
      )}

      <div>
        {onCancel && (
          <button type="button" onClick={onCancel}>
            Cancel
          </button>
        )}
        <button type="submit" disabled={form.submitting}>
          {form.submitting ? 'Saving…' : bookmark ? 'Save changes' : 'Save bookmark'}
        </button>
      </div>
    </form>
  );
}

export default BookmarkForm;
import { useRef, useState } from 'react';
import type { Bookmark, ReadingState } from '../../../shared/contracts.js';
import { DeleteConfirmation } from './DeleteConfirmation.js';

export interface BookmarkCardProps {
  bookmark: Bookmark;
  onReadingStateChange?: (bookmark: Bookmark, readingState: ReadingState) => void;
  onEdit?: (bookmark: Bookmark) => void;
  onDelete?: (bookmark: Bookmark) => void;
}

const readingStateLabels: Record<ReadingState, string> = {
  untracked: 'Untracked',
  to_read: 'To Read',
  read: 'Read',
};

const savedDateFormatter = new Intl.DateTimeFormat('en-US', {
  dateStyle: 'medium',
  timeZone: 'UTC',
});

export function formatSavedDate(timestamp: string): string {
  const date = new Date(timestamp);
  return Number.isNaN(date.getTime()) ? timestamp : savedDateFormatter.format(date);
}

export function BookmarkCard({
  bookmark,
  onReadingStateChange,
  onEdit,
  onDelete,
}: BookmarkCardProps) {
  const titleId = `bookmark-title-${bookmark.id}`;
  const [confirmingDelete, setConfirmingDelete] = useState(false);
  const deleteTrigger = useRef<HTMLButtonElement>(null);

  const cancelDelete = () => {
    setConfirmingDelete(false);
    window.setTimeout(() => deleteTrigger.current?.focus(), 0);
  };

  return (
    <article aria-labelledby={titleId}>
      <header>
        <h3 id={titleId}>
          <a href={bookmark.url} target="_blank" rel="noopener noreferrer">
            {bookmark.title}
          </a>
        </h3>
        <p>{bookmark.url}</p>
      </header>

      {bookmark.description && <p>{bookmark.description}</p>}

      <dl>
        <div>
          <dt>Saved</dt>
          <dd>
            <time dateTime={bookmark.createdAt}>{formatSavedDate(bookmark.createdAt)}</time>
          </dd>
        </div>
        <div>
          <dt>Reading status</dt>
          <dd>{readingStateLabels[bookmark.readingState]}</dd>
        </div>
      </dl>

      {bookmark.tags.length > 0 && (
        <ul aria-label={`Tags for ${bookmark.title}`}>
          {bookmark.tags.map((tag) => (
            <li key={tag}>{tag}</li>
          ))}
        </ul>
      )}

      {onReadingStateChange && (
        <button
          type="button"
          onClick={() =>
            onReadingStateChange(
              bookmark,
              bookmark.readingState === 'to_read' ? 'read' : 'to_read',
            )
          }
        >
          {bookmark.readingState === 'to_read' ? 'Mark as Read' : 'Mark as To Read'}
        </button>
      )}

      {onEdit && (
        <button type="button" onClick={() => onEdit(bookmark)}>
          Edit
        </button>
      )}
      {onDelete && (
        <button
          ref={deleteTrigger}
          type="button"
          hidden={confirmingDelete}
          onClick={() => setConfirmingDelete(true)}
        >
          Delete
        </button>
      )}
      {onDelete && confirmingDelete && (
        <DeleteConfirmation
          title={bookmark.title}
          onCancel={cancelDelete}
          onConfirm={() => onDelete(bookmark)}
        />
      )}
    </article>
  );
}

