*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  min-width: 20rem;
  background: var(--color-paper);
  font-family: var(--font-body);
  color: var(--color-ink);
  line-height: 1.55;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

body {
  min-height: 100vh;
  margin: 0;
  background:
    radial-gradient(circle at 8% 2%, rgb(216 74 47 / 9%), transparent 28rem),
    radial-gradient(circle at 92% 24%, rgb(12 113 108 / 8%), transparent 30rem),
    linear-gradient(180deg, #faf6ed 0%, var(--color-paper) 55%, #efe6d8 100%);
}

body::before {
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  content: '';
  opacity: 0.22;
  background-image: repeating-linear-gradient(
    0deg,
    transparent 0,
    transparent 3px,
    rgb(23 35 58 / 2%) 3px,
    rgb(23 35 58 / 2%) 4px
  );
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
select,
input[type='checkbox'] {
  cursor: pointer;
}

button {
  min-height: var(--control-height);
  padding: 0.65rem 1rem;
  border: 1px solid var(--color-ink);
  border-radius: var(--radius-sm);
  background: var(--color-ink);
  color: var(--color-surface);
  font-weight: 750;
  line-height: 1.15;
  transition:
    transform var(--transition-fast),
    box-shadow var(--transition-fast),
    background-color var(--transition-fast),
    border-color var(--transition-fast);
}

button:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 5px 0 rgb(23 35 58 / 16%);
  background: #263651;
}

button:active:not(:disabled) {
  transform: translateY(0);
  box-shadow: none;
}

button:disabled {
  cursor: wait;
  opacity: 0.62;
}

a {
  color: var(--color-teal);
  text-decoration-thickness: 0.08em;
  text-underline-offset: 0.18em;
}

a:hover {
  color: var(--color-accent-dark);
}

:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 3px;
}

::selection {
  background: var(--color-accent-soft);
  color: var(--color-ink);
}

h1,
h2,
h3,
p,
dl,
dd,
fieldset {
  margin-block-start: 0;
}

h1,
h2,
h3 {
  line-height: 1.08;
  text-wrap: balance;
}

p,
