*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  min-width: 20rem;
  background: var(--color-paper);
  font-family: var(--font-body);
  color: var(--color-ink);
  line-height: 1.55;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

body {
  min-height: 100vh;
  margin: 0;
  background:
    radial-gradient(circle at 8% 2%, rgb(216 74 47 / 9%), transparent 28rem),
    radial-gradient(circle at 92% 24%, rgb(12 113 108 / 8%), transparent 30rem),
    linear-gradient(180deg, #faf6ed 0%, var(--color-paper) 55%, #efe6d8 100%);
}

body::before {
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  content: '';
  opacity: 0.22;
  background-image: repeating-linear-gradient(
    0deg,
    transparent 0,
    transparent 3px,
    rgb(23 35 58 / 2%) 3px,
    rgb(23 35 58 / 2%) 4px
  );
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
select,
input[type='checkbox'] {
  cursor: pointer;
}

button {
  min-height: var(--control-height);
  padding: 0.65rem 1rem;
  border: 1px solid var(--color-ink);
  border-radius: var(--radius-sm);
  background: var(--color-ink);
  color: var(--color-surface);
  font-weight: 750;
  line-height: 1.15;
  transition:
    transform var(--transition-fast),
    box-shadow var(--transition-fast),
    background-color var(--transition-fast),
    border-color var(--transition-fast);
}

button:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 5px 0 rgb(23 35 58 / 16%);
  background: #263651;
}

button:active:not(:disabled) {
  transform: translateY(0);
  box-shadow: none;
}

button:disabled {
  cursor: wait;
  opacity: 0.62;
}

a {
  color: var(--color-teal);
  text-decoration-thickness: 0.08em;
  text-underline-offset: 0.18em;
}

a:hover {
  color: var(--color-accent-dark);
}

:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 3px;
}

::selection {
  background: var(--color-accent-soft);
  color: var(--color-ink);
}

h1,
h2,
h3,
p,
dl,
dd,
fieldset {
  margin-block-start: 0;
}

h1,
h2,
h3 {
  line-height: 1.08;
  text-wrap: balance;
}

p,
a,
dd,
li {
  overflow-wrap: anywhere;
}

input,
textarea,
select {
  width: 100%;
  min-height: var(--control-height);
  border: 1px solid var(--color-line-strong);
  border-radius: var(--radius-sm);
  background: var(--color-surface-raised);
  color: var(--color-ink);
}

input,
textarea {
  padding: 0.7rem 0.8rem;
}

select {
  padding: 0.65rem 2.4rem 0.65rem 0.8rem;
}

textarea {
  min-height: 7rem;
  resize: vertical;
}

input::placeholder,
textarea::placeholder {
  color: #7d7b78;
}

input[aria-invalid='true'],
textarea[aria-invalid='true'],
select[aria-invalid='true'] {
  border-color: var(--color-danger);
  background: #fff9f9;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
#root {
  min-height: 100vh;
}

main {
  width: min(100% - 2rem, var(--content-width));
  margin-inline: auto;
  padding-block: var(--space-5) var(--space-8);
}

main > header {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: var(--space-5);
  align-items: start;
  overflow: hidden;
  padding: clamp(1.25rem, 4vw, 3.5rem);
  border: 1px solid var(--color-ink);
  border-radius: var(--radius-lg);
  background: var(--color-ink);
  color: var(--color-surface);
  box-shadow: var(--shadow-lift);
}

main > header::after {
  position: absolute;
  right: -5rem;
  bottom: -7rem;
  width: 18rem;
  aspect-ratio: 1;
  border: 2.25rem solid rgb(255 255 255 / 7%);
  border-radius: 50%;
  content: '';
}

main > header > a {
  position: relative;
  z-index: 1;
  padding: 0.35rem 0.65rem;
  border: 1px solid rgb(255 255 255 / 35%);
  border-radius: 999px;
  color: white;
  font-family: var(--font-display);
  font-size: var(--text-lg);
  font-weight: 700;
  text-decoration: none;
}

main > header > div {
  position: relative;
  z-index: 1;
  max-width: 48rem;
}

main > header > div > p:first-child,
[role='tabpanel'] > div:first-child > p:first-child {
  margin-bottom: var(--space-2);
  color: #f2aa92;
  font-size: var(--text-xs);
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

main > header h1 {
  max-width: 12ch;
  margin-bottom: var(--space-4);
  font-family: var(--font-display);
  font-size: var(--text-display);
  font-weight: 500;
  letter-spacing: -0.045em;
}

main > header h1 + p {
  max-width: 43rem;
  margin-bottom: 0;
  color: #c8d1df;
  font-size: var(--text-lg);
}

main > header > button {
  position: relative;
  z-index: 1;
  border-color: var(--color-accent);
  background: var(--color-accent);
  color: white;
}

main > header > button:hover:not(:disabled) {
  background: #ec5a3d;
}

main > section[aria-labelledby='add-bookmark-heading'] {
  max-width: 52rem;
  margin: calc(var(--space-6) * -1) auto var(--space-6);
  padding: var(--space-6);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-lg);
  background: var(--color-surface);
  box-shadow: var(--shadow-lift);
  position: relative;
  z-index: 2;

